const body = $input.first()?.json?.body || $input.first()?.json || {};
const pages = Array.isArray(body.pages) && body.pages.length
  ? body.pages
  : [{
      page: body.page,
      text: body.text || body.pageText,
      scene: body.scene,
      imagePrompt: body.imagePrompt || body.prompt,
      negativePrompt: body.negativePrompt || body.negative_prompt
    }];

const title = String(body.title || body.bookTitle || 'Picture Book').trim();
const bookId = String(body.bookId || body.documentId || `book_${Date.now()}`);
const visualStyle = String(body.visualStyle || body.style || 'gentle watercolor children picture book illustration, warm soft colors, rounded shapes, hand-drawn texture').trim();
const defaultNegative = 'text, letters, words, subtitles, watermark, logo, scary, horror, violence, photorealistic, 3d render, distorted hands, extra limbs, bad anatomy, low quality, blurry, cropped';
const comfyuiUrls = [
  'https://vcbj5meqyp1y7ifw-8188.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8189.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8190.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8191.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8192.container.x-gpu.com'
];
const apiBaseUrl = String(body.apiBaseUrl || $env.API_BASE_URL || 'http://localhost:4000').replace(/\/$/, '');
const width = Math.max(512, Math.min(2048, Number(body.width) || 1280));
const height = Math.max(512, Math.min(2048, Number(body.height) || 720));
const steps = Math.max(4, Math.min(40, Number(body.steps) || 15));
const cfg = Number.isFinite(Number(body.cfg)) ? Number(body.cfg) : 1.5;
const sampler = String(body.sampler || 'euler');
const scheduler = String(body.scheduler || 'simple');
const baseSeed = Number.isFinite(Number(body.seed)) ? Number(body.seed) : Math.floor(Math.random() * 900000000000000);

const workflowTemplate = {
  '1': { inputs: { unet_name: String(body.unetName || 'z_image_turbo_bf16.safetensors'), weight_dtype: 'default' }, class_type: 'UNETLoader' },
  '2': { inputs: { vae_name: String(body.vaeName || 'ae.safetensors') }, class_type: 'VAELoader' },
  '3': { inputs: { clip_name: String(body.clipName || 'qwen_3_4b.safetensors'), type: String(body.clipType || 'lumina2'), device: 'default' }, class_type: 'CLIPLoader' },
  '4': { inputs: { shift: Number(body.shift) || 3, model: ['1', 0] }, class_type: 'ModelSamplingAuraFlow' },
  '5': { inputs: { width, height, batch_size: 1 }, class_type: 'EmptySD3LatentImage' },
  '6': { inputs: { text: '', clip: ['3', 0] }, class_type: 'CLIPTextEncode' },
  '7': { inputs: { text: '', clip: ['3', 0] }, class_type: 'CLIPTextEncode' },
  '8': { inputs: { seed: baseSeed, steps, cfg, sampler_name: sampler, scheduler, denoise: 1, model: ['4', 0], positive: ['6', 0], negative: ['7', 0], latent_image: ['5', 0] }, class_type: 'KSampler' },
  '9': { inputs: { samples: ['8', 0], vae: ['2', 0] }, class_type: 'VAEDecode' },
  '10': { inputs: { filename_prefix: 'PictureBook', images: ['9', 0] }, class_type: 'SaveImage' }
};

return pages.map((page, index) => {
  // Round-robin distribution keeps the task paired with the ComfyUI instance that accepted it.
  const comfyuiUrl = comfyuiUrls[index % comfyuiUrls.length];
  const pageNo = Number(page.page) || index + 1;
  const scene = String(page.scene || page.text || '').trim();
  const imagePrompt = String(page.imagePrompt || page.prompt || scene).trim();
  if (!imagePrompt) throw new Error(`Missing imagePrompt for page ${pageNo}.`);

  const workflow = JSON.parse(JSON.stringify(workflowTemplate));
  const positive = [
    `Children picture book illustration for page ${pageNo}.`,
    visualStyle,
    imagePrompt,
    scene ? `Scene details: ${scene}.` : '',
    'Full-bleed landscape illustration, clean composition, child-safe, warm emotional tone.',
    'No text, no captions, no speech bubbles, no visible letters.'
  ].filter(Boolean).join(' ');
  const negative = [defaultNegative, page.negativePrompt || page.negative_prompt || body.negativePrompt || body.negative_prompt || ''].filter(Boolean).join(', ');
  const safeTitle = title.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(0, 36) || 'PictureBook';

  workflow['6'].inputs.text = positive;
  workflow['7'].inputs.text = negative;
  workflow['8'].inputs.seed = baseSeed + pageNo;
  workflow['10'].inputs.filename_prefix = `PictureBook_${safeTitle}_P${String(pageNo).padStart(2, '0')}`;

  return { json: {
    bookId,
    title,
    page: pageNo,
    pageText: String(page.text || page.pageText || '').trim(),
    imagePrompt,
    negativePrompt: negative,
    width,
    height,
    comfyuiUrl,
    apiBaseUrl,
    comfyuiPayload: { prompt: workflow }
  } };
});

const prepared = $('Prepare ComfyUI Payload').all();
const responses = $input.all();
const assets = responses.map((item, index) => {
  const meta = prepared[index]?.json || {};
  const response = item.json || {};
  const executionId = response.prompt_id || response.id;
  if (!executionId) throw new Error(`ComfyUI did not return prompt_id for page ${meta.page || index + 1}.`);
  const statusUrl = `${meta.apiBaseUrl}/api/ai/task-status/${executionId}?useComfyUI=true&apiUrl=${encodeURIComponent(meta.comfyuiUrl)}`;
  return {
    executionId,
    promptId: executionId,
    workflowType: 'image',
    status: 'submitted',
    statusUrl,
    comfyuiUrl: meta.comfyuiUrl,
    bookId: meta.bookId,
    title: meta.title,
    page: meta.page || index + 1,
    pageText: meta.pageText || '',
    imagePrompt: meta.imagePrompt || '',
    width: meta.width,
    height: meta.height
  };
});
assets.sort((a, b) => a.page - b.page);
return [{ json: {
  success: true,
  status: 'submitted',
  count: assets.length,
  assets,
  firstAsset: assets[0] || null
} }];
